/** This compendium link macro will always call the most recent version from the compendium included with this module meaning you do not need to reimport newer versions. The source of the macros that get called is https://gitlab.com/symonsch/my-foundryvtt-macros/-/tree/main/PF2e */
/* Start of documentation from the original macro: */
/*
Welcome to the Conditions Manager.
This macro was designed to have a window that can be minimized when not needed or opened whenever to manage conditions.
It is mostly intended for those who want an easy to read condition manager without the need for modules.
All conditions are toggled on and off by having the tokens selected that you would apply the condition to and clicking the
name of the condition. If the condition can have a value, simply click the + to increase the value or the - to decrease.
The Clear a condition button is used to clear a specific condition off of a group of selected tokens.
This macro is loosely adapted from the Apply Conditions macro created by cepvep.
CSS design by websterguy
Added the ability to add Timed Effects that grant conditions for a specific amount of time.
Have the actor causing the effect selected and the ones the effect it being placed on targeted when in combat.
Added a checkbox to use Player's targets if in an active combat and the selected token is playerOwned.
Added the ability to clear all conditions on selected tokens.
Preselect targets(combat)/selected(outside of combat) tokens since the second dialog will not catch changes.
*/
/* End of original macro documentation. */

    async function _executeMacroByName(
        macroName,
        compendiumName = "xdy-pf2e-workbench.asymonous-benefactor-macros-internal"
    ) {
        const pack = game.packs.get(compendiumName);
        if (pack) {
            let macro = (await pack.getDocuments({name: macroName}))?.[0];
            if (macro) {
                if (!macro.canExecute)
                    macro = new macro.constructor(foundry.utils.mergeObject(macro.toObject(), {"-=_id": null, "ownership.default": CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER}, {performDeletions: true, inplace: true}));
                macro.execute();
            } else {
                ui.notifications.error(`Macro ${macroName} not found`);
            }
        } else {
            ui.notifications.error(`Compendium ${compendiumName} not found`);
        }
    }
    _executeMacroByName('XDY DO_NOT_IMPORT Conditions Manager');

    /* This compendium link macro is based on one originally posted by DrentalBot: https://discord.com/channels/880968862240239708/880975811279204402/910490804554973274; and modified by Mark Pearce https://discord.com/channels/880968862240239708/880969174661353484/972962446098702376 */
